import { Player, type PlayerAPI } from "bitmovin-player";
import { DefaultUIFactory, PremiereUIFactory } from "@showcase/ui-shared";
import "@showcase/ui-shared/css";

export function createPlayerWithUi(element: HTMLElement, playerLicense: string): {
  player: PlayerAPI;
  usePremiere: () => void;
  release: () => Promise<void>;
} {
  const player = new Player(element, { key: playerLicense, ui: false });
  let ui = DefaultUIFactory.buildDefaultUI(player, undefined, { hideDelay: -1 });

  return {
    player,
    usePremiere() {
      ui.release();
      ui = PremiereUIFactory.buildPremiereUI(player, {
        playbackSpeedSelectionEnabled: false,
      }, { hideDelay: -1 });
    },
    async release() {
      ui.release();
      await player.destroy();
    },
  };
}

.bmpui-ui-label-wallclock.bmpui-hidden,
.bmpui-ui-label-behindlive.bmpui-hidden {
  display: none;
}
